SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_input_issue (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, batch_id bigint, entity_id bigint, employee_id bigint, owner_id bigint, reviewer_id bigint, submitted_by bigint, proof_by bigint,
 kind varchar(32), status varchar(32), reason varchar(1000), evidence varchar(1000), review_opinion varchar(1000), request_key varchar(100), request_snapshot LONGTEXT,
 source_snapshot LONGTEXT, submitted_snapshot LONGTEXT, closed_snapshot LONGTEXT, reminder_state LONGTEXT, reminder_error varchar(1000), due_time datetime, closed_time datetime, creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0, UNIQUE KEY uk_input_issue_request(tenant_id,request_key), active_source varchar(128) GENERATED ALWAYS AS (CASE WHEN deleted=b'0' AND status IN ('OPEN','SUBMITTED') THEN CONCAT(batch_id,':',employee_id,':',kind) ELSE NULL END) STORED, UNIQUE KEY uk_input_issue_active(tenant_id,active_source), KEY idx_input_issue_due(tenant_id,status,due_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_input_issue_event (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, issue_id bigint, actor_id bigint, action varchar(32), reason varchar(1000), snapshot LONGTEXT, creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @parent=(SELECT id FROM system_menu WHERE path='/hrm-payroll' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '薪酬输入缺口工单','hrm:payroll:issue:query',2,@parent,'input-issue','ep:warning','hrm/payroll/input-issue/index','HrmPayrollInputIssue' WHERE @parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:issue:query' AND deleted=0);
SET @issue=(SELECT id FROM system_menu WHERE permission='hrm:payroll:issue:query' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '分派及处理输入缺口','hrm:payroll:issue:update',3,@issue,'','','','' WHERE @issue IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:issue:update' AND deleted=0);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '独立复核输入缺口','hrm:payroll:issue:review',3,@issue,'','','','' WHERE @issue IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:issue:review' AND deleted=0);
SET @portal=COALESCE((SELECT parent_id FROM system_menu WHERE component='hrm/portal/home/index' AND deleted=0 LIMIT 1),0);
INSERT INTO system_menu(name,permission,type,parent_id,path,component,component_name) SELECT '我的薪酬工单','hrm:portal:query',2,@portal,'payroll-input-issue','hrm/portal/salary/input-issue/index','HrmPortalPayrollInputIssue' WHERE NOT EXISTS(SELECT 1 FROM system_menu WHERE component='hrm/portal/salary/input-issue/index' AND deleted=0);
INSERT INTO system_notify_template(name,code,nickname,content,type,params,status,remark) SELECT '薪酬输入缺口逾期提醒','hrm_payroll_input_issue_overdue','人力资源','薪酬输入缺口工单 {caseId}（{period}，{kind}）已超过期限 {dueTime}，请查看我的薪酬工单。',2,'["caseId","period","kind","dueTime"]',0,'仅工单编号、期间、来源类型及期限，不含薪资、税务身份或原证明' WHERE NOT EXISTS(SELECT 1 FROM system_notify_template WHERE code='hrm_payroll_input_issue_overdue' AND deleted=0);
INSERT INTO infra_job(name,status,handler_name,handler_param,cron_expression,retry_count,retry_interval,monitor_timeout) SELECT '薪酬输入缺口逾期站内提醒',2,'hrmPayrollInputIssueReminderJob','','0 0 9 * * ?',0,0,0 WHERE NOT EXISTS(SELECT 1 FROM infra_job WHERE handler_name='hrmPayrollInputIssueReminderJob' AND deleted=0);

-- Repair only the exact legacy mis-encoding of these installer-owned labels.
SET @hrm_label='薪酬输入缺口工单'; UPDATE system_menu SET name=@hrm_label WHERE permission='hrm:payroll:issue:query' AND deleted=0 AND BINARY name=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='分派及处理输入缺口'; UPDATE system_menu SET name=@hrm_label WHERE permission='hrm:payroll:issue:update' AND deleted=0 AND BINARY name=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='独立复核输入缺口'; UPDATE system_menu SET name=@hrm_label WHERE permission='hrm:payroll:issue:review' AND deleted=0 AND BINARY name=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='我的薪酬工单'; UPDATE system_menu SET name=@hrm_label WHERE component='hrm/portal/salary/input-issue/index' AND deleted=0 AND BINARY name=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='薪酬输入缺口逾期提醒'; UPDATE system_notify_template SET name=@hrm_label WHERE code='hrm_payroll_input_issue_overdue' AND deleted=0 AND BINARY name=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='人力资源'; UPDATE system_notify_template SET nickname=@hrm_label WHERE code='hrm_payroll_input_issue_overdue' AND deleted=0 AND BINARY nickname=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='薪酬输入缺口工单 {caseId}（{period}，{kind}）已超过期限 {dueTime}，请查看我的薪酬工单。'; UPDATE system_notify_template SET content=@hrm_label WHERE code='hrm_payroll_input_issue_overdue' AND deleted=0 AND BINARY content=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
SET @hrm_label='仅工单编号、期间、来源类型及期限，不含薪资、税务身份或原证明'; UPDATE system_notify_template SET remark=@hrm_label WHERE code='hrm_payroll_input_issue_overdue' AND deleted=0 AND BINARY remark=BINARY CONVERT(CONVERT(CAST(@hrm_label AS BINARY) USING latin1) USING utf8mb4);
